import {esc,icon,btn,field,select,fallbackThumb} from './views.js';
import {calculate,money,materialColors,requirements} from './core.js';
import {alerts,totals,salePreview,peekTicket,saleReturns} from './workshop.js';
const cash=(s,n)=>new Intl.NumberFormat('es-MX',{style:'currency',currency:s.currency}).format(n);
const colorStack=(colors=[])=>`<span class="color-stack">${colors.map(c=>`<i class="color-dot" style="background:${esc(c)}"></i>`).join('')}</span>`;
const draftTotal=(s,d)=>{try{return salePreview(s,d.cart,d.reserve!==false).total;}catch{return d.cart.reduce((n,l)=>n+(+l.qty||0)*(+l.unitPrice||0),0);}};
const moneyOr=(currency,value)=>money(value,currency);
export function inventoryPage(s,u,filaments=''){
 const tab=u.inventoryTab||'products',low=alerts(s),kinds={products:'product',supplies:'supply',assets:'asset'},kind=kinds[tab],items=tab==='products'?s.products:tab==='assets'?s.assets:s.supplies;
 const create={products:['Nuevo producto','new-product'],materials:['Nuevo filamento','new-material'],supplies:['Nuevo insumo','new-supply'],assets:['Nuevo artículo','new-asset']};
 return `<div class="page-heading"><div><div class="eyebrow">LO QUE TIENES EN EL TALLER</div><h1>Inventario.</h1><p>Productos, filamentos, insumos y equipo. Todo editable, con existencias reales.</p></div><div class="heading-actions">${btn('Registrar compra','purchase','plus')}${create[tab]?btn(create[tab][0],create[tab][1],'plus','primary'):''}</div></div>
 <div class="inventory-summary"><div><b>${s.products.filter(x=>!x.retired).reduce((n,x)=>n+x.stock,0)}</b><span>Piezas terminadas</span></div><div><b>${s.materials.filter(x=>!x.retired).reduce((n,x)=>n+x.stock,0).toLocaleString('es-MX',{maximumFractionDigits:1})} g</b><span>Filamento disponible</span></div><div><b>${s.supplies.filter(x=>!x.retired).length}</b><span>Tipos de insumos</span></div><div class="${low.length?'danger-text':''}"><b>${low.length}</b><span>Avisos de reposición</span></div></div>
 <div class="tabs">${[['products','Productos terminados','box'],['materials','Filamentos','spool'],['supplies','Insumos','layers'],['assets','Equipo y otros','printer'],['movements','Movimientos','file']].map(([id,label,ico])=>`<button class="tab ${id===tab?'active':''}" data-action="inventory-tab" data-tab="${id}">${icon(ico)}${label}</button>`).join('')}</div>
 ${low.length?`<details class="stock-alert"><summary>${low.length} artículo(s) por reponer</summary><div class="alert-chips">${low.map(x=>`<span><b>${esc(x.name)}</b> · ${Number(x.stock.toFixed(2))} ${esc(x.unit)}${x.stock<=0?' · AGOTADO':''}</span>`).join('')}</div></details>`:''}
 <div class="inventory-section section-space">${tab==='materials'?filaments:tab==='movements'?movementTable(s):`${tab==='assets'?`<div class="section-header"><h3>Impresoras configuradas</h3>${btn('Gestionar en Ajustes','nav','settings','small','data-view="settings"')}</div><div class="printer-grid">${s.printers.map(p=>`<div class="panel"><b>${esc(p.printer)}</b><p class="small muted">${p.bedX} × ${p.bedY} × ${p.bedZ} mm · ${cash(s,p.machineCost)}</p>${btn('Editar en Ajustes','edit-printer-inventory','edit','small',`data-id="${esc(p.id)}"`)}</div>`).join('')}</div><h3 class="section-space">Herramientas, equipo y otros artículos</h3>`:''}
 <div class="table-wrap section-space"><table><thead><tr><th>${tab==='products'?'Producto / SKU':'Artículo'}</th><th>Existencias</th><th>Aviso mínimo</th><th>Costo unitario</th>${tab==='products'?'<th>Venta</th>':'<th>Unidad / paquete</th>'}<th>Acciones</th></tr></thead><tbody>${items.filter(x=>!x.retired).map(x=>`<tr><td><b>${esc(x.name)}</b><p class="small muted">${esc(x.sku||x.category||'')}${tab==='products'&&x.sourceObjectId?' · Vinculado a modelo 3D':''}</p></td><td class="${x.stock<=x.minStock?'danger-text':''}"><b>${Number(x.stock.toFixed(2))}</b> ${esc(x.unit||'pzas')}</td><td>${x.minStock}</td><td>${cash(s,x.unitCost)}</td><td>${tab==='products'?cash(s,x.price):esc(x.unit)+' · '+x.packUnits+' / paquete'}</td><td><div class="flex wrap">${btn('Editar',tab==='supplies'?'edit-supply':'edit-stock-item','edit','small',`data-kind="${kind}" data-id="${esc(x.id)}"`)}${tab==='products'?btn('Registrar producción','produce-product','layers','small',`data-id="${esc(x.id)}" ${x.sourceObjectId?'':'disabled'}`):''}${btn('Comprar','purchase','','small',`data-kind="${kind}" data-id="${esc(x.id)}"`)}${btn('Eliminar',tab==='supplies'?'delete-supply':'delete-stock-item','trash','small danger',`data-kind="${kind}" data-id="${esc(x.id)}"`)}</div></td></tr>`).join('')||`<tr><td colspan="6">${tab==='products'?'Agrega las piezas que ya tienes fabricadas. Si las produces aquí, vincula el producto a un objeto de la estantería.':tab==='supplies'?'Agrega argollas, imanes, pegamento, empaques o pintura y reparte su consumo entre objetos.':'Registra cualquier artículo físico del taller, con su cantidad y costo.'}</td></tr>`}</tbody></table></div><p class="short-note">Editar existencias registra un ajuste de conteo. Las compras suman stock y descuentan su importe del saldo. ${tab==='products'?'Registrar producción consume materiales y agrega piezas terminadas; venderlas después solo descuenta esas piezas.':''}</p>`}</div>
 <details class="panel section-space"><summary>Artículos retirados</summary>${[...s.materials.map(x=>({...x,kind:'material'})),...s.supplies.map(x=>({...x,kind:'supply'})),...s.products.map(x=>({...x,kind:'product'})),...s.assets.map(x=>({...x,kind:'asset'}))].filter(x=>x.retired).map(x=>`<div class="between cost-row"><b>${esc(x.name)}</b>${btn('Restaurar','restore-stock','','small',`data-kind="${x.kind}" data-id="${esc(x.id)}"`)}</div>`).join('')||'<p class="short-note">No hay artículos retirados.</p>'}</details>`;
}
export function movementTable(s,salesOnly=false){
 const rows=s.ledger.filter(t=>salesOnly?['sale','return'].includes(t.type):!['sale','return'].includes(t.type)).slice().reverse();
 const names={sale:'Venta',return:'Devolución',purchase:'Compra',production:'Producción',print:'Impresión',adjustment:'Ajuste'};
 return `<div class="section-header"><h3>${salesOnly?'Tickets de venta':'Compras, producción y ajustes'}</h3><div class="flex">${salesOnly?btn('Corte parcial','partial-cut','clock','small')+btn('Corte de caja','full-cut','calculator','small'):''}${btn('Exportar movimientos','export-ledger','download','small')}</div></div><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Movimiento</th><th>Detalle</th><th>Importe</th><th></th></tr></thead><tbody>${rows.map(t=>`<tr class="${t.voided?'voided':''}"><td>${new Date(t.date).toLocaleString('es-MX')}</td><td>${esc(t.ticket||names[t.type])}<p class="small muted">${t.voided?'Anulado':names[t.type]}${t.type==='return'?` · ${esc(t.saleTicket||'')}`:''}</p></td><td class="wrap">${esc(t.type==='sale'?t.lines.map(l=>`${l.qty} × ${l.name}${l.colorRequests?.length?' ['+l.colorRequests.map(c=>c.name).join(', ')+']':l.requestedColorName?' ['+l.requestedColorName+']':''}`).join(' · '):t.type==='return'?(t.items||[]).map(l=>`${l.qty} × ${l.name}`).join(' · '):t.movements.map(m=>`${m.delta!=null?(m.delta>=0?'+':'−'):t.type==='purchase'?'+':'−'}${Number(m.units.toFixed(2))} ${m.unit} · ${m.name}`).join(' · '))}${t.note?`<p class="small muted">${esc(t.note)}</p>`:''}</td><td class="${t.type==='return'?'danger-text':''}">${t.type==='return'?'− ':''}${money(t.total,t.currency)}</td><td><div class="flex wrap">${t.type==='sale'?btn('Ticket','view-ticket','file','small',`data-id="${esc(t.id)}"`):''}${t.type==='return'?btn('Recibo','view-return','file','small',`data-id="${esc(t.id)}"`):''}${!t.voided&&t.type==='sale'?btn('Devolución','return-sale','back','small',`data-id="${esc(t.id)}"`):''}${t.voided?'':btn(t.type==='return'?'Anular devolución':'Anular','void-transaction','trash','small danger',`data-id="${esc(t.id)}"`)}</div></td></tr>`).join('')||'<tr><td colspan="5">Todavía no hay movimientos.</td></tr>'}</tbody></table></div>`;
}
function posTabs(tab){return `<div class="tabs">${[['sale','Caja','calculator'],['history','Tickets','file'],['reports','Resultados','layers'],['cuts','Cortes','download']].map(([id,n,i])=>`<button class="tab ${id===tab?'active':''}" data-action="pos-tab" data-tab="${id}">${icon(i)}${n}</button>`).join('')}</div>`;}
function cutsPage(s){
 const cuts=(s.cashCuts||[]).slice().reverse();
 return `<div class="section-header"><div><h3>Cortes de caja</h3><p class="short-note">Un corte parcial informa sin reiniciar el periodo. El corte total inicia un periodo nuevo y conserva todas las ventas.</p></div><div class="flex wrap">${btn('Corte parcial','partial-cut','clock','small')}${btn('Corte total','full-cut','calculator','small primary')}</div></div><div class="cut-list">${cuts.map(c=>`<div class="panel cut-row"><div><div class="between"><b>${esc(c.number)} · ${c.type==='full'?'Corte total':'Corte parcial'}</b><span class="badge ${c.type==='full'?'':'outline'}">${new Date(c.date).toLocaleString('es-MX')}</span></div><p class="small muted">${new Date(c.from).toLocaleString('es-MX')} — ${new Date(c.to).toLocaleString('es-MX')} · ${c.report?.counts?.sales||0} venta(s)</p></div><div class="cut-row-total"><strong>${cash(s,c.report?.balance||0)}</strong><span>neto de caja</span></div><div class="flex wrap">${btn('Ver','view-cut','file','small',`data-id="${esc(c.id)}"`)}${btn('Imprimir','print-cut','printer','small',`data-id="${esc(c.id)}"`)}${btn('Virtual','export-cut-html','download','small',`data-id="${esc(c.id)}"`)}</div></div>`).join('')||'<div class="empty"><h3>Aún no hay cortes</h3><p>Genera el primero cuando termines una jornada o quieras revisar el periodo actual.</p></div>'}</div>`;
}
export function posPage(s,u){
 u.cart??=[];const tab=u.posTab||'sale',t=totals(s);
 if(tab==='history')return `<div class="page-heading"><div><div class="eyebrow">CAJA DEL TALLER</div><h1>Tickets de venta.</h1><p>Consulta, imprime, devuelve o anula movimientos.</p></div><div class="heading-actions">${btn('Volver a caja','pos-tab','back','primary','data-tab="sale"')}</div></div>${posTabs(tab)}${movementTable(s,true)}`;
 if(tab==='reports')return `<div class="page-heading"><div><div class="eyebrow">CAJA DEL TALLER</div><h1>Ventas y resultados.</h1></div><div class="heading-actions">${btn('Volver a caja','pos-tab','back','primary','data-tab="sale"')}</div></div>${posTabs(tab)}<div class="pos-stats">${[['Ventas netas',t.sales],['Compras y reposiciones',t.purchases],['Saldo · ventas − compras',t.balance],['Utilidad estimada',t.profit]].map(([l,v])=>`<div class="panel"><span class="small muted">${l}</span><strong class="stat-amount ${v<0?'danger-text':''}">${cash(s,v)}</strong></div>`).join('')}</div><p class="short-note">El saldo cuenta ventas netas de devoluciones menos compras registradas. La utilidad estimada descuenta los costos de los productos vendidos. Importes en ${esc(s.currency)}, sin impuestos.</p>`;
 if(tab==='cuts')return `<div class="page-heading"><div><div class="eyebrow">CAJA DEL TALLER</div><h1>Cortes.</h1><p>Todo lo vendido, con precio, hora y forma de pago.</p></div><div class="heading-actions">${btn('Volver a caja','pos-tab','back','primary','data-tab="sale"')}</div></div>${posTabs(tab)}${cutsPage(s)}`;
 const term=(u.posSearch||'').toLowerCase(),source=u.posSource||'products';let catalog=[];
 if(source==='products')catalog=s.products.filter(x=>!x.retired).map(x=>({...x,kind:'product',key:x.id,thumbnail:s.boxes.find(b=>b.id===x.sourceBoxId)?.thumbnail}));else catalog=s.boxes.filter(b=>!b.archived).flatMap(b=>b.objects.map(o=>{const price=calculate(o,s.materials,s.settings);return {kind:'model',id:o.id,key:b.id+'|'+o.id,boxId:b.id,name:o.name,sku:b.name,price:price.price,missing:price.missing,thumbnail:b.thumbnail};}));
 catalog=catalog.filter(x=>(x.name+' '+(x.sku||'')).toLowerCase().includes(term));let preview,error;try{preview=salePreview(s,u.cart,u.saleReserve!==false);}catch(e){error=e.message;}
 const drafts=(s.posDrafts||[]).filter(d=>d.cart?.length),current=drafts.find(d=>d.id===u.draftId),ticket=current?.number||peekTicket(s);
 return `<div class="page-heading pos-heading"><div><div class="eyebrow">CAJA 01 · ${new Date().toLocaleDateString('es-MX')}</div><h1>Punto de venta.</h1><p>Elige productos, personaliza colores y registra el cobro.</p></div><div class="heading-actions">${btn('Inventario','nav','box','','data-view="inventory"')}${btn('Nueva venta','new-sale','plus','primary')}</div></div>${posTabs('sale')}
 ${drafts.length?`<div class="pos-drafts"><div class="pos-drafts-label">${icon('clock')} Tickets sin cobrar</div><div class="pos-draft-list">${drafts.map(d=>`<button class="pos-draft-chip ${d.id===u.draftId?'active':''}" data-action="open-draft" data-id="${esc(d.id)}"><b>${esc(d.number)}</b><span>${esc(d.customer||'Sin cliente')} · ${cash(s,draftTotal(s,d))}</span></button>`).join('')}</div></div>`:''}
 <div class="pos-layout"><section class="pos-catalog"><div class="toolbar"><label class="search">${icon('search')}<input id="pos-search" value="${esc(u.posSearch||'')}" placeholder="Buscar producto, nombre o SKU…" autocomplete="off"></label></div><div class="pos-source"><button class="${source==='products'?'active':''}" data-action="pos-source" data-source="products">Productos en inventario</button><button class="${source==='models'?'active':''}" data-action="pos-source" data-source="models">Fabricar bajo pedido</button></div><p class="short-note">${source==='products'?'El cobro descuenta piezas terminadas del inventario.':'El cobro registra el pedido y descuenta los materiales de los colores elegidos. Evita volver a descontarlos como producción.'}</p><div class="pos-product-grid section-space">${catalog.map(x=>`<button class="pos-product ${x.missing?'needs-slice':''}" data-action="pos-add" data-kind="${x.kind}" data-id="${esc(x.id)}" data-box="${esc(x.boxId||'')}"><div class="pos-product-picture"><img src="${esc(x.thumbnail||fallbackThumb())}" alt="" loading="lazy"></div><div class="pos-product-body"><span class="tiny muted">${esc(x.sku||'PRODUCTO')}</span><b>${esc(x.name)}</b><div class="between"><strong>${x.missing?'Por laminar':cash(s,x.price)}</strong><span class="${x.kind==='product'&&x.stock<=0?'danger-text':''}">${x.kind==='product'?`${x.stock} en stock`:icon('plus')}</span></div></div></button>`).join('')||`<div class="empty">${icon('box')}<h3>${term?'Sin coincidencias':'Tu mostrador empieza aquí'}</h3><p>${source==='products'?'Agrega tus productos físicos en Inventario o selecciona Fabricar bajo pedido.':'Agrega objetos a la estantería y lamínalos para conocer su costo.'}</p>${btn('Abrir inventario','nav','box','primary','data-view="inventory"')}</div>`}</div></section>
 <aside class="pos-ticket"><div class="pos-ticket-head"><div><span class="eyebrow">TICKET ${esc(ticket)}</span><h2>${current?'Venta abierta':'Nuevo ticket'}</h2></div><span class="badge">${u.cart.reduce((n,l)=>n+l.qty,0)} piezas</span></div><div class="pos-cart-lines">${u.cart.map((l,i)=>`<div class="pos-cart-line"><div class="between"><b>${esc(l.name)}</b><button class="icon-btn" data-action="pos-remove" data-index="${i}" aria-label="Quitar ${esc(l.name)}">${icon('close')}</button></div><small class="muted">${l.kind==='product'?'Producto terminado':'Fabricar bajo pedido'} · ${esc(ticket)}</small>${cartColors(s,l,i)}<div class="pos-cart-controls"><div class="quantity-stepper"><button data-action="pos-step" data-index="${i}" data-delta="-1" aria-label="Restar">−</button><input type="number" min="1" step="1" value="${l.qty}" data-pos-qty="${i}" aria-label="Cantidad"><button data-action="pos-step" data-index="${i}" data-delta="1" aria-label="Sumar">+</button></div><label class="small">Precio unitario<input type="number" min="0" step=".01" value="${l.unitPrice}" data-pos-price="${i}"></label><strong>${cash(s,l.qty*l.unitPrice)}</strong></div></div>`).join('')||'<div class="empty"><p>Agrega un producto para comenzar.</p></div>'}</div>
 <div class="pos-ticket-footer"><label class="field">Cliente / referencia<input id="pos-customer" value="${esc(u.posCustomer||'')}" placeholder="Venta al público"></label><label class="field section-space">Nota<input id="pos-note" value="${esc(u.saleNote||'')}" placeholder="Detalles del pedido"></label>${source==='models'||u.cart.some(l=>l.kind!=='product')?`<label class="field inline section-space"><input type="checkbox" id="pos-reserve" ${u.saleReserve!==false?'checked':''}> Incluir reserva de filamento (${s.settings.error}%)</label>`:''}${preview?.shortages.length?`<div class="pos-shortage">${preview.shortages.map(m=>`<p>Faltan ${m.shortage.toFixed(2)} ${esc(m.unit)} · ${esc(m.name)}</p>`).join('')}</div>`:''}${error&&u.cart.length?`<p class="danger-text section-space">${esc(error)}</p>`:''}<div class="pos-grand-total"><span>Total</span><strong>${cash(s,preview?.total||0)}</strong></div>${btn('Cobrar','pos-checkout','calculator','primary full',!preview||preview.shortages.length||!u.cart.length?'disabled':'')}<div class="flex section-space wrap">${current?btn('Descartar ticket','discard-draft','trash','small danger',`data-id="${esc(current.id)}"`):''}</div><p class="short-note">Registro local del cobro · ${esc(s.currency)}. Los tickets abiertos se guardan aunque cierres la app.</p></div></aside></div>`;
}
function cartColors(s,line,index){
 if(line.kind==='product'){
  const colors=s.materials.filter(m=>!m.retired);
  if(!colors.length)return '';
  const selected=colors.find(m=>m.id===line.requestedColor);
  return `<div class="pos-line-colors"><label>Color solicitado<select data-pos-color="${index}|0"><option value="">Sin preferencia</option>${colors.map(m=>`<option value="${esc(m.id)}" ${m.id===line.requestedColor?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label>${selected?colorStack(materialColors(selected)):''}</div>`;
 }
 const b=s.boxes.find(x=>x.id===line.boxId),o=b?.objects.find(x=>x.id===line.objectId);if(!o)return '';
 const rows=requirements(o,s.materials,s.settings,line.qty||1).rows;
 if(!rows.length)return '';
 return `<div class="pos-line-colors">${rows.map((row,j)=>{const value=line.colors?.[j]||row.id,selected=s.materials.find(m=>m.id===value)||row;return `<label>Color ${j+1}${rows.length>1?' / '+rows.length:''}<span class="pos-color-pick">${colorStack(materialColors(selected))}<select data-pos-color="${index}|${j}">${s.materials.filter(m=>!m.retired).map(m=>`<option value="${esc(m.id)}" ${m.id===value?'selected':''}>${esc(m.name)}</option>`).join('')}</select></span></label>`;}).join('')}</div>`;
}
export function ticketMarkup(t,settings={},returns=[]){
 const refunded=returns.filter(r=>!r.voided),returned=refunded.reduce((n,r)=>n+r.total,0);
 return `<div class="receipt"><img src="./logo.svg" alt="Jackalope" width="50"><h2>${esc(settings.businessName||'3D-Woods')}</h2><p class="tiny muted">${esc(settings.businessTagline||'Un bosque de ideas')}</p><b>${esc(t.ticket||t.id)}</b><p>${new Date(t.date).toLocaleString('es-MX')}<br>${esc(t.customer||'Venta al público')}</p><div class="receipt-lines">${t.lines.map(l=>`<div><span>${l.qty} × ${esc(l.name)}${l.colorRequests?.length?`<small>${l.colorRequests.map(c=>`${colorStack(c.colors)} ${esc(c.name)}`).join(' · ')}</small>`:l.requestedColorName?`<small>${colorStack(l.requestedColors)} ${esc(l.requestedColorName)}</small>`:''}<small>${money(l.unitPrice,t.currency)} / unidad</small></span><b>${money(l.qty*l.unitPrice,t.currency)}</b></div>`).join('')}</div><div class="between"><b>TOTAL</b><strong>${money(t.total,t.currency)}</strong></div>${returned?`<div class="between receipt-return"><b>DEVUELTO</b><strong>− ${money(returned,t.currency)}</strong></div><div class="between"><b>NETO</b><strong>${money(t.total-returned,t.currency)}</strong></div>`:''}<p>${esc(t.payment?.method||'Registro')} · Recibido: ${money(t.payment?.received??t.total,t.currency)}<br>Cambio: ${money(t.payment?.change||0,t.currency)}</p>${t.note?`<p>${esc(t.note)}</p>`:''}${refunded.length?`<p class="small muted">${refunded.map(r=>`${esc(r.ticket)}: − ${money(r.total,t.currency)}`).join('<br>')}</p>`:''}<p class="tiny muted">Comprobante de control interno · Sin valor fiscal${t.voided?' · ANULADO':''}</p></div>`;
}
export function returnMarkup(t,sale,settings={}){
 return `<div class="receipt"><img src="./logo.svg" alt="Jackalope" width="50"><h2>${esc(settings.businessName||'3D-Woods')}</h2><b>${esc(t.ticket)}</b><p>${new Date(t.date).toLocaleString('es-MX')}<br>Venta original: ${esc(sale?.ticket||t.saleTicket||'')}<br>${esc(t.customer||'Venta al público')}</p><div class="receipt-lines">${(t.items||[]).map(l=>`<div><span>${l.qty} × ${esc(l.name)}<small>${money(l.unitPrice,t.currency)} / unidad</small></span><b>${money(l.qty*l.unitPrice,t.currency)}</b></div>`).join('')}</div><div class="between"><b>REEMBOLSO</b><strong>${money(t.total,t.currency)}</strong></div><p>Forma: ${esc(t.payment?.method||'efectivo')}</p>${t.note?`<p>${esc(t.note)}</p>`:''}<p class="tiny muted">Comprobante de devolución · Sin valor fiscal</p></div>`;
}
export function cashCutMarkup(cut,settings={}){
 const r=cut.report||{};
 return `<div class="receipt cut-summary"><img src="./logo.svg" alt="Jackalope" width="50"><h2>${esc(settings.businessName||'3D-Woods')}</h2><b>${esc(cut.number)} · ${cut.type==='full'?'CORTE TOTAL':'CORTE PARCIAL'}</b><p>${new Date(cut.from).toLocaleString('es-MX')}<br>${new Date(cut.to).toLocaleString('es-MX')}</p><div class="cut-kpis"><div><span>Ventas</span><strong>${moneyOr(settings.currency,r.salesTotal||0)}</strong></div><div><span>Devoluciones</span><strong>− ${moneyOr(settings.currency,r.returnsTotal||0)}</strong></div><div><span>Compras</span><strong>− ${moneyOr(settings.currency,r.purchasesTotal||0)}</strong></div><div><span>Neto</span><strong>${moneyOr(settings.currency,r.balance||0)}</strong></div><div><span>Utilidad</span><strong>${moneyOr(settings.currency,r.profit||0)}</strong></div></div><p class="small muted">${r.counts?.sales||0} venta(s) · ${r.counts?.pieces||0} pieza(s) · ${r.returns?.length||0} devolución(es)</p>${cut.note?`<p>${esc(cut.note)}</p>`:''}<p class="tiny muted">${cut.type==='full'?'El corte total inicia un periodo nuevo; las ventas se conservan.':'Corte informativo: no reinicia el periodo.'}</p></div>`;
}
export {cash};
